  try {
    const res = await fetch(url3, {
      headers: { "User-Agent": "india-stock-mcp/1.0.0" },
      signal: AbortSignal.timeout(timeoutMs)
    });
    if (!res.ok)
      throw new Error(`HTTP ${res.status} from ${url3}`);
    return await res.json();
  } catch (e) {
    if (attempt >= 2)
      throw e;
    await new Promise((r) => setTimeout(r, 1e3));
    return fetchJSON(url3, timeoutMs, attempt + 1);
  }
