server.tool("get_index", "Get live data for a market index: price, change, P/E, P/B, year high/low, advances/declines. Available: NIFTY 50, NIFTY BANK, NIFTY IT, NIFTY MIDCAP 100, NIFTY SMALLCAP 100, NIFTY AUTO, NIFTY PHARMA, SENSEX, and all other NSE indices.", {
  index: external_exports.string().describe("Index name e.g. 'NIFTY 50', 'NIFTY BANK', 'NIFTY IT', 'SENSEX', 'NIFTY MIDCAP 100'")
}, async ({ index }) => {
  try {
    const name = index.toUpperCase().trim();
    const INDEX_ALIASES = {
      "SENSEX": "^BSESN",
      "BSE SENSEX": "^BSESN",
      "NIFTY": "NIFTY 50",
      "BANKNIFTY": "NIFTY BANK",
      "BANK NIFTY": "NIFTY BANK",
      "FINNIFTY": "NIFTY FINANCIAL SERVICES"
    };
    const target = INDEX_ALIASES[name] ?? name;
    if (target.startsWith("^")) {
      const q = await getQuote(target);
      return ok({
        source: "Yahoo Finance",
        index: name,
        price: q.regularMarketPrice,
        change: q.regularMarketChange,
        changePct: q.regularMarketChangePercent,
        open: q.regularMarketOpen,
        high: q.regularMarketDayHigh,
        low: q.regularMarketDayLow,
        previousClose: q.regularMarketPreviousClose,
        yearHigh: q.fiftyTwoWeekHigh,
        yearLow: q.fiftyTwoWeekLow
      });
    }
    const all5 = await listIndices();
    const match = (all5?.data ?? []).find((d) => d.index?.toUpperCase() === target || d.indexSymbol?.toUpperCase() === target);
    if (!match) {
      const available = (all5?.data ?? []).map((d) => d.index).slice(0, 50);
      return err(`Index '${index}' not found. Available NSE indices include: ${available.join(", ")}`);
    }
    return ok({
      source: "NSE",
      index: match.index,
      last: match.last,
      variation: match.variation,
      percentChange: match.percentChange,
      open: match.open,
      high: match.high,
      low: match.low,
      previousClose: match.previousClose,
      yearHigh: match.yearHigh,
      yearLow: match.yearLow,
      pe: match.pe,
      pb: match.pb,
      dividendYield: match.dy,
      advances: match.advances,
      declines: match.declines
    });
  } catch (e) {
    return err(e.message);
  }
});
