server.tool("compare_funds", "Compare 2\u20134 mutual funds side by side: latest NAV and % return over the chosen period.", {
  scheme_codes: external_exports.array(external_exports.string()).min(2).max(4).describe('Array of AMFI scheme codes e.g. ["122639", "120503"]'),
  days: external_exports.number().min(7).max(3650).default(365).describe("Comparison period in days (NAV entries are trading days)")
}, async ({ scheme_codes, days }) => {
  try {
    const results = await Promise.allSettled(scheme_codes.map((code) => getFundHistory(code)));
    const comparison = results.map((r, i) => {
      if (r.status === "rejected")
        return { code: scheme_codes[i], error: r.reason?.message };
      const d = r.value;
      const cutoff = new Date(Date.now() - days * 24 * 60 * 60 * 1e3);
      const history = (d.data || []).filter((e) => {
        const [dd, mm, yyyy] = (e.date || "").split("-");
        return /* @__PURE__ */ new Date(`${yyyy}-${mm}-${dd}`) >= cutoff;
      });
      if (history.length === 0) {
        return {
          code: scheme_codes[i],
          name: d.meta?.scheme_name,
          error: `No NAV data in the last ${days} days \u2014 scheme may be invalid or discontinued`
        };
      }
      const latest = parseFloat(history[0]?.nav || "0");
      const oldest = parseFloat(history[history.length - 1]?.nav || "0");
      const returnPct = oldest > 0 ? +((latest - oldest) / oldest * 100).toFixed(2) : null;
      return {
        code: scheme_codes[i],
        name: d.meta?.scheme_name,
        category: d.meta?.scheme_category,
        fundHouse: d.meta?.fund_house,
        latestNAV: latest,
        latestDate: history[0]?.date,
        periodDays: days,
        returnPct
      };
    });
    return ok({ comparison, periodDays: days });
  } catch (e) {
    return err(e.message);
  }
});
server.tool("portfolio_summary", "Analyze a stock portfolio. Pass holdings with buy price and quantity, get current value, P&L, allocation breakdown, and gain/loss per holding. Max 20 holdings.", {
  holdings: external_exports.array(external_exports.object({
    symbol: external_exports.string().describe("NSE symbol"),
    quantity: external_exports.number().positive().describe("Number of shares held"),
    buyPrice: external_exports.number().positive().describe("Average buy price per share in INR")
  })).min(1).max(20).describe("Array of stock holdings")
}, async ({ holdings }) => {
  try {
    const results = await Promise.allSettled(holdings.map((h) => getQuote(h.symbol)));
    let totalInvested = 0;
    let totalCurrent = 0;
    let failedCount = 0;
    const positions = results.map((r, i) => {
      const h = holdings[i];
      const invested = h.buyPrice * h.quantity;
      if (r.status === "rejected" || r.value?.regularMarketPrice == null) {
        failedCount++;
        return {
          symbol: h.symbol,
          quantity: h.quantity,
          buyPrice: h.buyPrice,
          invested,
          error: "Could not fetch current price \u2014 excluded from totals"
        };
      }
      totalInvested += invested;
      const q = r.value;
      const currentPrice = q.regularMarketPrice;
      const currentValue = currentPrice * h.quantity;
      const pnl = currentValue - invested;
      totalCurrent += currentValue;
      return {
        symbol: h.symbol.toUpperCase(),
        name: q.shortName,
        quantity: h.quantity,
        buyPrice: h.buyPrice,
        currentPrice,
        invested: +invested.toFixed(2),
        currentValue: +currentValue.toFixed(2),
        pnl: +pnl.toFixed(2),
        pnlPct: +(pnl / invested * 100).toFixed(2),
        allocation: 0
        // filled below
      };
    });
    positions.forEach((p) => {
      if (typeof p.currentValue === "number" && totalCurrent > 0) {
        p.allocation = +(p.currentValue / totalCurrent * 100).toFixed(2);
      }
    });
    const totalPnL = totalCurrent - totalInvested;
    return ok({
      summary: {
        totalInvested: +totalInvested.toFixed(2),
        totalCurrentValue: +totalCurrent.toFixed(2),
        totalPnL: +totalPnL.toFixed(2),
        totalPnLPct: totalInvested > 0 ? +(totalPnL / totalInvested * 100).toFixed(2) : null,
        holdingCount: holdings.length,
        excludedCount: failedCount || void 0
      },
      positions
    });
  } catch (e) {
    return err(e.message);
  }
});
